use lang::frontend::{self, CompileLimits};
use lang_bytecode::unit as wire;
use std::path::Path;

fn main() {
    let source = Path::new("/private/tmp/lang-m5-legacy-probe.lang");
    let limits = CompileLimits::default();
    let analysis = frontend::analyze_file(source, source.parent().unwrap(), limits);
    let typed = analysis.result.expect("historical source is valid");
    let program = frontend::compile_script(&typed, &analysis.sources, limits).unwrap();
    let bytes = wire::encode(&program, wire::CodecLimits::default()).unwrap();
    std::fs::write("/private/tmp/lang-m5-legacy-probe.langbc", bytes).unwrap();
}
